PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE commits (
            hash TEXT PRIMARY KEY,
            author TEXT,
            date TEXT,
            message TEXT,
            source_branch TEXT
        );
CREATE TABLE file_changes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            commit_hash TEXT,
            file_path TEXT,
            file_name TEXT,
            change_type TEXT,
            file_type TEXT,
            FOREIGN KEY (commit_hash) REFERENCES commits(hash)
        );
